cd /testbed && cat > reproduce2.py << 'EOF'
import django
from django.conf import settings
settings.configure(
    DATABASES={'default': {'ENGINE': 'django.db.backends.sqlite3', 'NAME': ':memory:'}},
    INSTALLED_APPS=['django.contrib.contenttypes', 'django.contrib.auth'],
)
django.setup()

from django.db import models, connection
from django.db.models import F

# Test 1: Expression in ordering (F().desc())
class Parent1(models.Model):
    name = models.CharField(max_length=100)
    class Meta:
        ordering = [F('name').desc()]
        app_label = 'test'

class Child1(Parent1):
    class Meta:
        app_label = 'test'

# Test 2: String ordering (normal case, should still work)
class Parent2(models.Model):
    name = models.CharField(max_length=100)
    class Meta:
        ordering = ['-name']
        app_label = 'test'

class Child2(Parent2):
    class Meta:
        app_label = 'test'

# Test 3: Mix of expressions and strings
class Parent3(models.Model):
    name = models.CharField(max_length=100)
    age = models.IntegerField(default=0)
    class Meta:
        ordering = [F('name').asc(), '-age']
        app_label = 'test'

class Child3(Parent3):
    class Meta:
        app_label = 'test'

# Test 4: F expression without .asc()/.desc() (should default to asc)
class Parent4(models.Model):
    name = models.CharField(max_length=100)
    class Meta:
        ordering = [F('name')]
        app_label = 'test'

class Child4(Parent4):
    class Meta:
        app_label = 'test'

# Create all tables
with connection.schema_editor() as schema_editor:
    for model in [Parent1, Child1, Parent2, Child2, Parent3, Child3, Parent4, Child4]:
        schema_editor.create_model(model)

tests = [
    ("Test 1: F().desc() ordering", Child1.objects.order_by('parent1_ptr')),
    ("Test 2: String ordering (normal)", Child2.objects.order_by('parent2_ptr')),
    ("Test 3: Mixed ordering", Child3.objects.order_by('parent3_ptr')),
    ("Test 4: F() without direction", Child4.objects.order_by('parent4_ptr')),
    ("Test 5: Reverse order on expression", Child1.objects.order_by('-parent1_ptr')),
]

for label, qs in tests:
    try:
        print(f"{label}: {qs.query}")
        print("  -> SUCCESS")
    except Exception as e:
        print(f"  -> ERROR: {type(e).__name__}: {e}")
EOF
python reproduce2.py

